// Atlas logo assets (base64-encoded PNGs), for use in the Word/PowerPoint
// exports. Replaces the earlier placeholder, which was actually the
// Institutional Adviser firm mark reused as a stand-in -- Atlas now has its
// own standalone mark ("Ascent": two nested navy/teal chevrons) distinct
// from the parent firm's branding, per Peter's 2026-08-07 request.
//
// Four assets, two color variants x two compositions:
//  - ATLAS_MARK_PNG_BASE64 / ATLAS_LOCKUP_PNG_BASE64: navy+teal on
//    transparent, for light backgrounds -- the small running header/footer
//    badge repeated on every page/slide (mark) and the cover/title page
//    lockup (icon + "ATLAS" wordmark), both used against the exports' usual
//    white page background.
//  - ATLAS_MARK_WHITE_PNG_BASE64 / ATLAS_LOCKUP_WHITE_PNG_BASE64: white+teal
//    on transparent, for the navy cover-slide/cover-page background (a navy
//    mark would be invisible against navy) -- see addCoverSlide()/the docx
//    cover page.
// getAtlasLogoBuffer()/getAtlasLogoDataUri() kept as the same function names
// as before this change so any existing per-page logo wiring didn't need to
// change, just now points at the new mark.
// Source: generated from a new SVG concept (2026-08-07), rasterized via
// ImageMagick/librsvg in the build sandbox -- navy #0f2540 / teal #2f6f6f
// match the site's existing --navy/--accent palette; white variants swap the
// navy fill for white, keeping the same teal.
const ATLAS_MARK_PNG_BASE64 = "";
const ATLAS_LOCKUP_PNG_BASE64 = "";
const ATLAS_MARK_WHITE_PNG_BASE64 = "";
const ATLAS_LOCKUP_WHITE_PNG_BASE64 = "";

function getAtlasLogoBuffer() {
  return Buffer.from(ATLAS_MARK_PNG_BASE64, "base64");
}

function getAtlasLogoDataUri() {
  return `image/png;base64,${ATLAS_MARK_PNG_BASE64}`;
}

function getAtlasLockupBuffer() {
  return Buffer.from(ATLAS_LOCKUP_PNG_BASE64, "base64");
}

function getAtlasLockupDataUri() {
  return `image/png;base64,${ATLAS_LOCKUP_PNG_BASE64}`;
}

function getAtlasLockupWhiteBuffer() {
  return Buffer.from(ATLAS_LOCKUP_WHITE_PNG_BASE64, "base64");
}

function getAtlasLockupWhiteDataUri() {
  return `image/png;base64,${ATLAS_LOCKUP_WHITE_PNG_BASE64}`;
}

function getAtlasMarkWhiteBuffer() {
  return Buffer.from(ATLAS_MARK_WHITE_PNG_BASE64, "base64");
}

function getAtlasMarkWhiteDataUri() {
  return `image/png;base64,${ATLAS_MARK_WHITE_PNG_BASE64}`;
}

module.exports = {
  ATLAS_MARK_PNG_BASE64, ATLAS_LOCKUP_PNG_BASE64, ATLAS_MARK_WHITE_PNG_BASE64, ATLAS_LOCKUP_WHITE_PNG_BASE64,
  getAtlasLogoBuffer, getAtlasLogoDataUri,
  getAtlasLockupBuffer, getAtlasLockupDataUri,
  getAtlasLockupWhiteBuffer, getAtlasLockupWhiteDataUri,
  getAtlasMarkWhiteBuffer, getAtlasMarkWhiteDataUri
};
